// ─── IKI KATMANLI LIMIT ─────────────────────────────────────────────────
// 1) IP basina GUNLUK limit: tek kullanicinin sistemi spam'lemesini engeller.
// 2) GLOBAL AYLIK limit: Apify TikTok Trending calistirmasi basina ~$0.10
//    (20 sonuc, TR proxy filtresi dahil) -- TUM kullanicilar arasinda
//    paylasilan gercek butceyi korur. IP limiti bunu KORUMAZ -- 50 farkli
//    kullanici gunde 1'er istek atsa bile toplam kota hizla biter. Apify'in
//    aylik $5 ucretsiz kredisi ~50 calistirmaya denk geldigi icin, pay
//    birakmak icin 50 degil 45'te kesiyoruz.
const PER_IP_DAILY_LIMIT = 50;
// NOT: 'Build Search Query' 2 yerine 4 hashtag kullanmaya basladi (fyp,
// kesfet, turkiye, trendturkiye) -- Apify muhtemelen her hashtag icin ayri
// ucretlendiriyor, yani calistirma basina maliyet ~2 katina cikabilir. Ilk
// gercek test sonrasi Apify Storage/Usage sayfasindan gercek maliyeti
// kontrol edip bu sayiyi ona gore ayarla -- simdilik ihtiyatli baslangic.
const GLOBAL_MONTHLY_SEARCH_LIMIT = 25;

const ip = $input.first().json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || $input.first().json.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const monthKey = today.slice(0, 7); // 'YYYY-MM'
const ipKey = 'rl_trend_' + ip + '_' + today;
const globalKey = 'rl_trend_global_' + monthKey;

const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};

const ipCount = staticData.rateLimits[ipKey] || 0;
const globalCount = staticData.rateLimits[globalKey] || 0;

if (ipCount >= PER_IP_DAILY_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'ip_daily' } }];
}
if (globalCount >= GLOBAL_MONTHLY_SEARCH_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'global_monthly' } }];
}

staticData.rateLimits[ipKey] = ipCount + 1;
staticData.rateLimits[globalKey] = globalCount + 1;

const body = $input.first().json.body || $input.first().json;
return [{ json: { rateLimitExceeded: false, ...body } }];

const data = $input.first().json;
const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 8000,
  messages: [{ role: 'user', content: data.prompt || '' }]
};
return [{ json: { ...data, apiBody } }];

// ─── DÜZELTME NOTLARI ────────────────────────────────────────────────────
// 1) "MiniMax API" (HTTP Request) node'u SADECE ham API cevabını döndürür;
//    mode/email/biz/sector/tones/hour/days gibi orijinal form alanlarını
//    kendiliğinden taşımaz. Bu yüzden context'i "Build Request Body"
//    node'undan referansla ($('Build Request Body')) geri çekiyoruz.
// 2) MiniMax-M3 reasoning modeli olduğu için cevap önce bir düşünce süreci
//    (<think>...</think>) içerir, gerçek JSON bundan SONRA gelir.
// 3) "mode" alanı sadece 3 geçerli değerden biri olabilir; güvenli varsayılan.
// 4) YENİ: JSON.parse basarisiz olursa artik SESSIZCE videos:[] dondurmuyoruz.
//    Once yaygin LLM JSON hatalarini (trailing comma, kontrol karakteri)
//    onarmayi deniyoruz; hala basarisizsa bunu ACIK BIR HATA olarak
//    isaretliyoruz (parseError=true) ki "Store Job Result" bunu job'a
//    status:'error' olarak yazsin — kullanici sessizce bos sonuc gormesin.

const ctx = $('Build Request Body').first().json;
const apiData = $input.first().json;

let text = apiData.choices?.[0]?.message?.content || '';

const thinkEnd = text.lastIndexOf('</think>');
if (thinkEnd !== -1) text = text.slice(thinkEnd + '</think>'.length);

const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);

function tryParseJson(raw) {
  try {
    return { ok: true, value: JSON.parse(raw) };
  } catch (e1) {
    // Yaygin LLM JSON hatalarini onarmayi dene: trailing comma, kontrol karakterleri
    const repaired = raw
      .replace(/,\s*([\]}])/g, '$1')
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
    try {
      return { ok: true, value: JSON.parse(repaired) };
    } catch (e2) {
      return { ok: false, error: e1.message || String(e1) };
    }
  }
}

function extractErrorPosition(msg) {
  const m = /position (\d+)/.exec(msg || '');
  return m ? parseInt(m[1], 10) : null;
}

function buildDebugSnippet(raw, errMsg) {
  const pos = extractErrorPosition(errMsg);
  if (pos !== null) {
    const start = Math.max(0, pos - 350);
    const end = Math.min(raw.length, pos + 150);
    // >>> <<< isaretleri tam hata konumunu gosterir
    const marker = Math.min(pos, raw.length) - start;
    return raw.slice(start, start + marker) + ' >>>HATA_BURADA<<< ' + raw.slice(start + marker, end);
  }
  return raw.slice(0, 800);
}

const parsed = tryParseJson(text);
let result;
let parseError = null;
let debugSnippet = null;
if (parsed.ok) {
  result = parsed.value;
} else {
  result = { videos: [], ctaText: '' };
  parseError = parsed.error;
  debugSnippet = buildDebugSnippet(text, parsed.error);
}

const videos = result.videos || [];
const dateStr = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
const sectorText = (ctx.sector === 'ALL' || !ctx.sector) ? 'Tüm Sektörler' : ctx.sector;
const tonesText = (ctx.tones || []).join(' + ');
const bizText = ctx.biz || 'İşletmeniz';

let emailContent = `Merhaba! ${bizText} için ${dateStr} tarihli trend video fikirleri:\n\n`;
videos.forEach(v => {
  emailContent += `#${v.rank} — ${v.title}\n`;
  emailContent += `Platform: ${v.platform} | Trend: ${v.trendScore || 'N/A'}\n`;
  emailContent += `Etiketler: ${(v.tags || []).join(', ')}\n`;
  emailContent += `Neden trend: ${v.whyTrending || ''}\n`;
  emailContent += `Markanıza uyarlama: ${v.adaptation || ''}\n\n---\n\n`;
});

const realSourcesHtml = (ctx.searchResultsRaw && ctx.searchResultsRaw.length)
  ? `<div style="margin-top:1.5rem;padding-top:1rem;border-top:1px dashed #E2E0D8"><div style="font-size:12px;color:#6B6963;font-weight:500;margin-bottom:.5rem">Bulunan gercek kaynaklar (ilham icin):</div>` +
    [...ctx.searchResultsRaw].sort((a,b) => (b.playCount||0)-(a.playCount||0)).slice(0, 6).map(r => `<div style="font-size:12px;margin-bottom:.35rem"><a href="${r.webVideoUrl}" style="color:#1D9E75;text-decoration:none" target="_blank">@${(r.authorMeta && r.authorMeta.name) || 'bilinmiyor'} — ${(r.playCount||0).toLocaleString('tr-TR')} izlenme</a></div>`).join('') +
    `</div>`
  : '';

const htmlBody = `<!DOCTYPE html><html lang="tr"><head><meta charset="UTF-8"></head><body style="font-family:system-ui,sans-serif;background:#F7F6F2;padding:2rem"><div style="max-width:680px;margin:0 auto;background:#fff;border-radius:16px;padding:2rem;border:0.5px solid #E2E0D8"><div style="color:#1D9E75;font-size:13px;font-weight:500;letter-spacing:.04em;margin-bottom:1.5rem">KOLAY KOBI — TREND VIDEO BULTENI</div><h1 style="font-size:22px;color:#1C1B19;margin-bottom:.4rem">Gunun Trend Video Fikirleri</h1><p style="font-size:14px;color:#6B6963;margin-bottom:2rem"><strong>${bizText}</strong> — ${sectorText}<br/>Ton: ${tonesText}<br/>Tarih: ${dateStr}</p>` + videos.map(v => `<div style="border:0.5px solid #E2E0D8;border-radius:12px;padding:1rem;margin-bottom:1rem"><div style="display:flex;align-items:center;gap:10px;margin-bottom:.75rem"><div style="width:32px;height:32px;border-radius:50%;background:#1D9E75;color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:600">${v.rank}</div><div style="font-size:15px;font-weight:500;color:#1C1B19">${v.title}</div></div><div style="font-size:12px;color:#6B6963;margin-bottom:.5rem">${v.platform} | Trend: ${v.trendScore || 'N/A'}</div><div style="background:#DCF8C6;border-radius:0 12px 12px 12px;padding:10px 12px;font-size:13px;color:#1C1B19;line-height:1.6;margin-bottom:.5rem">${v.whyTrending || ''}</div><div style="background:#F7F6F2;border-radius:8px;padding:8px 10px;font-size:12px;color:#6B6963"><strong style="color:#1D9E75">Markaniza uyarlama:</strong> ${v.adaptation || ''}</div>${(v.tags && v.tags.length) ? `<div style="margin-top:.5rem">${v.tags.map(t => `<span style="font-size:11px;padding:2px 8px;background:#F0FAF6;border:0.5px solid #9FE1CB;border-radius:6px;color:#085041;margin-right:4px">${t}</span>`).join('')}</div>` : ''}</div>`).join('') + realSourcesHtml + `<div style="background:#F0FAF6;border-radius:8px;padding:1rem;margin-top:1.5rem;text-align:center"><p style="font-size:13px;color:#0F6E56;margin:0">Bu rapor Kolay KOBİ Trend Video Bulucu ile oluşturuldu.</p><a href="https://kolaykobi.com" style="display:inline-block;background:#1D9E75;color:#fff;padding:10px 24px;border-radius:8px;text-decoration:none;font-size:14px;margin-top:.75rem">Kolay KOBİ'yi Ac</a></div></div></body></html>`;

const VALID_MODES = ['instant', 'once', 'schedule'];
const safeMode = VALID_MODES.includes(ctx.mode) ? ctx.mode : 'instant';

const realSources = ctx.searchResultsRaw || [];

return [{ json: {
  content: [{ type: 'text', text }],
  realSources,
  email: ctx.email || '',
  biz: bizText,
  sector: ctx.sector || '',
  tones: ctx.tones || [],
  mode: safeMode,
  hour: ctx.hour || '',
  days: ctx.days || [],
  audience: ctx.audience || '',
  note: ctx.note || '',
  prompt: ctx.prompt || '',
  emailContent,
  htmlBody,
  videos,
  ctaText: result.ctaText || '',
  parseError: parseError,
  rawModelTextSnippet: parseError ? debugSnippet : undefined,
  rawModelTextFull: parseError ? text : undefined,
} }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.schedules) staticData.schedules = {};
const id = 'sch_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
staticData.schedules[id] = {
  id,
  biz: data.biz || 'İşletme',
  sector: data.sector || 'ALL',
  email: data.email || '',
  tones: data.tones || [],
  audience: data.audience || '',
  note: data.note || '',
  prompt: data.prompt || '',
  hour: data.hour,
  days: data.days || [],
  createdAt: new Date().toISOString(),
  active: true,
};
return [{ json: { ...data, scheduleId: id, scheduleSaved: true } }];

// Webhook zaten 'Respond With Job ID' ile cevap verdi; burada tekrar
// HTTP yaniti DONMUYORUZ, sadece sonucu static data'ya job_id altinda yaziyoruz.
//
// YENI: "Response Transform" JSON.parse basarisiz olduysa (parseError dolu),
// bunu ARTIK sessiz bir "completed, videos:[]" olarak degil, acik bir
// status:'error' olarak isaretliyoruz — boylece kullanici gercek nedeni gorur.
const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const rt = $('Response Transform').first().json;
const payload = { ...rt, ...$json };

if (staticData.jobs && staticData.jobs[jobId]) {
  if (rt.parseError) {
    staticData.jobs[jobId] = {
      status: 'error',
      createdAt: staticData.jobs[jobId].createdAt,
      error: 'AI çıktısı geçerli JSON değildi: ' + rt.parseError + (rt.rawModelTextSnippet ? ' | Ham metin (ilk 800 karakter): ' + rt.rawModelTextSnippet : ''),
    };
  } else {
    staticData.jobs[jobId] = { status: 'completed', createdAt: staticData.jobs[jobId].createdAt, ...payload };
  }
}
return [{ json: payload }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobs) staticData.jobs = {};
// 30 dakikadan eski job kayitlarini temizle (static data sismesin)
const now = Date.now();
Object.keys(staticData.jobs).forEach(id => {
  if (now - (staticData.jobs[id].createdAt || 0) > 30 * 60 * 1000) delete staticData.jobs[id];
});
const jobId = now.toString(36) + Math.random().toString(36).slice(2, 10);
staticData.jobs[jobId] = { status: 'pending', createdAt: now };
return [{ json: { ...data, jobId } }];

// DUZELTME: onceki versiyon "err.error" bir OBJE oldugunda onu dogrudan
// error alanina yaziyordu; bu da istemci tarafinda "[object Object]" olarak
// gorunuyordu. Artik hatanin gercek metnini cok katmanli/guvenli sekilde
// cikariyoruz, boylece gercek MiniMax/n8n hatasini goruruz.
const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const err = $input.first().json;

function extractMessage(e) {
  if (!e) return 'Bilinmeyen hata';
  if (typeof e === 'string') return e;
  if (typeof e.message === 'string' && e.message) return e.message;
  if (typeof e.error === 'string' && e.error) return e.error;
  if (e.error && typeof e.error === 'object') {
    if (typeof e.error.message === 'string' && e.error.message) return e.error.message;
    if (typeof e.error.error === 'string' && e.error.error) return e.error.error;
    try { return JSON.stringify(e.error).slice(0, 400); } catch (_) {}
  }
  if (typeof e.description === 'string' && e.description) return e.description;
  if (typeof e.statusCode !== 'undefined') return `HTTP ${e.statusCode}: ${JSON.stringify(e).slice(0, 300)}`;
  try { return JSON.stringify(e).slice(0, 400); } catch (_) { return 'Bilinmeyen hata (JSON.stringify basarisiz)'; }
}

const errorMessage = extractMessage(err);

if (staticData.jobs && staticData.jobs[jobId]) {
  staticData.jobs[jobId] = { status: 'error', createdAt: staticData.jobs[jobId].createdAt, error: errorMessage };
}
return [{ json: { ok: false, error: errorMessage } }];

const q = $input.first().json.query || {};
const jobId = q.jobId;
const staticData = $getWorkflowStaticData('global');
const job = (staticData.jobs || {})[jobId];
if (!job) return [{ json: { status: 'not_found' } }];
return [{ json: job }];

const data = $input.first().json;
// Kullanicinin istedigi: sektore ozel arama DEGIL, genel olarak GERCEKTEN
// trend olan (yuksek izlenmeli) videolar. Bunlar sonradan MiniMax tarafindan
// sektore uyarlanacak (penguen -> lojistik mantigi). Bu yuzden sabit,
// genis kapsamli trend hashtag'leri kullaniyoruz, sektore gore degil.
// 'turkiye' ve 'trendturkiye' eklendi: 'fyp' ve 'kesfet' global etiketler
// oldugu icin sonuclarin cogu Turkce olmayan icerik getiriyordu -- bu
// ikisi Turkiye'deki kullanicilarin gordugu/kullandigi trendlere agirlik
// verip Turkce/yerel sonuc oranini artiriyor.
const hashtags = ['fyp', 'keşfet', 'turkiye', 'trendturkiye'];
return [{ json: { ...data, hashtags } }];

// Apify TikTok Trending sonuclarini prompta ekliyoruz. HTTP node context'i
// tasimadigi icin ('Build Search Query'den referansla geri cekiyoruz.
const ctx = $('Build Search Query').first().json;
const items = $input.all().map(i => i.json);
// Apify hata dondurduyse (yanlis token, kota vb.) tek bir item icinde
// 'error' alani olur; gercek veri geldiyse dogrudan video dizisi gelir.
const isError = items.length === 1 && items[0] && items[0].error;
const videos = (!isError && items.length) ? items : [];

let searchBlock;
if (videos.length) {
  const top = videos.slice(0, 10).sort((a, b) => (b.playCount || 0) - (a.playCount || 0));
  searchBlock = '\n\n═══ GERÇEK TREND TIKTOK VİDEOLARI (bugün bulundu, gerçek izlenme sayılarıyla) ═══\n' +
    top.map((v, i) => `${i + 1}. @${v.authorMeta?.name || 'bilinmiyor'} — ${(v.playCount || 0).toLocaleString('tr-TR')} izlenme, ${(v.diggCount || 0).toLocaleString('tr-TR')} beğeni\n   Açıklama: ${(v.text || '').slice(0, 150)}\n   Link: ${v.webVideoUrl || ''}`).join('\n') +
    '\n\nBu videolar SEKTÖRE ÖZEL DEĞİL — genel olarak trend olmuş gerçek videolar. Senin görevin: bu videoların formatini/konseptini (penguen yürüyüşü → lojistik örneğindeki gibi) işletmenin sektörüne UYARLAMAK. Hangi videodan esinlendiysen, o videonun gerçek linkini adaptation alanında ya da ayrı bir \'inspiredBy\' alanında belirtebilirsin ama uydurma link üretme.\n\nÖNEMLİ FİLTRE: yukarıdaki listedeki bazı videolar tekil/kişiye özel içerik olabilir (bir kişinin o anki hikayesi, yemek tarifi, kişisel itiraf vb.) — bunlar başka bir işletmeye UYARLANAMAZ, sadece o kişiye özeldür. SADECE soyutlanabilir bir FORMAT/KONSEPT içeren videoları seç (bir mizah kalıbı, bir çekim tekniği, bir meydan okuma/challenge, tekrarlanabilir bir yapı — penguen yürüyüşü örneğindeki gibi). Uyarlanabilir bir format bulamadığın videoları listeden ATLA, doldurmak için zorlama.';
} else {
  searchBlock = '\n\n(NOT: gerçek trend verisi bu çalıştırmada alınamadı, mevcut bilgine dayanarak üret.)';
}

const augmentedPrompt = (ctx.prompt || '') + searchBlock;
return [{ json: { ...ctx, prompt: augmentedPrompt, searchResultsRaw: videos.length ? videos : null } }];
